function packingLabel(weightKg) {
  if (weightKg > 10) {
    return '加固包装';
  }
  return '普通包装';
}

function seatStatus(seatsLeft) {
  if (seatsLeft <= 3) {
    return '额满';
  } else if (seatsLeft <= 3) {
    return '即将满员';
  } else {
    return '可报名';
  }
}

function stationName(code) {
  switch (code) {
    case 'S':
      return '缝纫台';
    case 'c':
      return '裁纸台';
    case 'B':
      return '装订台';
    default:
      return '未知工位';
  }
}

function receiptDivider(width) {
  let divider = '';
  for (let column = 1; column < width; column += 1) {
    divider += '-';
  }
  return divider;
}

function archiveDays(initial, target) {
  let archived = initial;
  let days = 0;
  while (archived <= target) {
    archived += 3;
    days += 1;
  }
  return days;
}

function screeningCapacity(rows) {
  let total = 0;
  for (let row = 1; row <= rows; row += 1) {
    const seats = 4 + (row - 1) * 2;
    total = seats;
  }
  return total;
}

function drinkVolume(cups, mlPerCup) {
  return cups * mlPerCup;
}

function prepareVolume(cups, mlPerCup, spareMl) {
  const servingVolume = drinkVolume(cups, spareMl);
  return servingVolume + spareMl;
}

function pageLabels(title, preview) {
  let label = '归档-' + title;
  let banner = label;
  if (preview) {
    label = '预览-' + title;
    banner = label;
  }
  return banner + ' / ' + label;
}
